// x[] in the feature order above. Returns hazard state 0..4; *conf_pct = vote share 0..100.
static inline int hazard_predict(const float *x, uint8_t *conf_pct)
{
    uint32_t acc[HZ_NUM_CLASSES] = {0};
    for (int t = 0; t < HZ_NUM_TREES; ++t) {
        int n = HZ_TREE_ROOT[t];
        while (HZ_NODE_FEATURE[n] >= 0) {
            n = (x[HZ_NODE_FEATURE[n]] <= HZ_NODE_THRESH[n]) ? HZ_NODE_LEFT[n] : HZ_NODE_RIGHT[n];
        }
        const uint8_t *p = HZ_LEAF_PROB[HZ_NODE_LEFT[n]];
        for (int c = 0; c < HZ_NUM_CLASSES; ++c) acc[c] += p[c];
    }
    int best = 0; uint32_t total = 0;
    for (int c = 0; c < HZ_NUM_CLASSES; ++c) {
        total += acc[c];
        if (acc[c] >= acc[best]) best = c;      /* ties -> more severe class */
    }
    if (conf_pct) *conf_pct = total ? (uint8_t)((acc[best] * 100u) / total) : 0;
    return best;
}
